import type { StudyCourse, StudyLesson, StudyQuestion } from "./academy-types";

// A alternativa correta muda de posição de forma estável: rascunhos mantêm o
// mesmo significado entre visitas. Todas as perguntas são autorais e ligadas a aulas.
type QuestionSeed = [prompt: string, answer: string, distractors: [string, string, string], explanation: string];
function question(id: string, lessonId: string, [prompt, answer, distractors, explanation]: QuestionSeed): StudyQuestion {
  const correct = [...id].reduce((sum, char) => sum + char.charCodeAt(0), 0) % 4;
  const options = [...distractors]; options.splice(correct, 0, answer);
  return { id, lessonId, prompt, options, correct, explanation };
}
type LessonSeed = { id: string; title: string; sections: [string, string][]; takeaways: string[]; example: string; application: string; questions: [QuestionSeed, QuestionSeed, QuestionSeed, QuestionSeed] };
function lesson(seed: LessonSeed): StudyLesson {
  const words = [...seed.sections.map(section => section[1]), seed.example, seed.application, ...seed.takeaways].join(" ").split(/\s+/).length;
  const { questions, ...content } = seed;
  return { ...content, sections: seed.sections.map(([heading, text]) => ({ heading, text })), minutes: Math.max(3, Math.ceil(words / 160)), activity: question(`a-${seed.id}`, seed.id, questions[0]), additionalActivities: [question(`a-${seed.id}-2`, seed.id, questions[1]), question(`a-${seed.id}-3`, seed.id, questions[2])], final: question(`f-${seed.id}`, seed.id, questions[3]) };
}

