export function deepenExistingLesson(item: StudyLesson): StudyLesson {
  const extra = deepening[item.id];
  if (!extra) return item;
  return { ...item, sections: [...item.sections, { heading: extra.heading, text: extra.text }], additionalActivities: extra.questions.map((seed, index) => question(`a-${item.id}-${index + 2}`, item.id, seed)) };
}
